[business_research] {
  "collection_management": {
    "process_flow": "采用线性、不可逆的“库前区”工艺流线，形成“洁污梯度”：卸货平台（设地磅）→ 封闭车位的货箱转运 → 暂存/隔离间（可调温湿，48-72小时观察与检疫）→ 拆箱作业间（缓冲室、独立风管与初效过滤，降低粉尘与气味）→ 鉴选/编目室（可记录与比对）→ 摄影/数字采集室（标准化布光）→ 包装材料库 → 入库通道（直达库房）。“洁污分区”与“动静分区”叠加：拆箱/检视区设独立排风与封闭围护（相对负压），数字采集与编目区为低噪声、恒定光照环境；温湿采用梯度过渡，避免温差与霉变风险。",
    "key_rooms": [
      "卸货平台（封闭车位、可洗车位、地磅）",
      "暂存/隔离间（可调温湿、静压缓冲与观察窗）",
      "拆箱作业间/缓冲间（独立排风与初效过滤）",
      "鉴选/编目室（可调台面与记录区）",
      "摄影/数字采集室（标准化灯光、静音、可调台面）",
      "包装材料库（防虫、防霉、无酸材料）",
      "入库通道/闸机",
      "快件收发室（外接门禁，邮件/小件消毒）
    ],
    "security_level": "库前区为全馆高安防等级分区（至少二级）：采用双门互锁、访客登记与陪同制度；独立视频监控、24小时门岗与中控；出入口设门禁分级（员工卡+临时证、访客陪同），关键节点设置金属/爆炸物探测（根据藏品特性启用）；所有门窗/卷帘具备延时报警；藏品转运采用密闭车与箱内条码追踪，作业全程留痕；敏感时段进入白名单模式，联动消防排烟与疏散策略。"
  },
  "research_conservation": {
    "labs_requirements": "文物修复与标本制作室采用北向为主、可遮阳的恒定自然光与高显色人工补光；独立排风与局部抽排（有机溶剂/酸碱/粉尘源），新风与回风独立，设置初效+中效+末端HEPA/活性炭（VOCs）三级过滤；温湿度可分区调控（目标18-22℃、40-55%RH，波动±2℃、±5%RH）；振动敏感设备区与走廊采取隔振与减振构造（预留局部浮筑地板）；地面承重不小于500 kg/m²（含文物台车与器材），化学清洗区耐酸碱、耐磨并设防渗与地漏；声学控制（≤45 dBA），粉尘源与脆弱标本分区；紫外/红外过滤窗膜并设温湿度记录。",
    "equipment_space": "预留大件仪器位（如光谱/能谱、显微成像台、3D扫描站）及其周围检修空间与电源负载（含UPS与冷却/制水位置）；天平/显微观察台局部防风；危险品库（通风防爆/防渗，酸碱与溶剂分类存放，独立消防）；干燥与恒温恒湿间设置循环风道与冷/热源；维修通道与设备吊装口（货运电梯旁、可上锁）。"
  },
  "admin_office": {
    "zoning": "将行政办公区与业务科研区“分而不离”：行政区靠近公共入口与对外大厅，便于综合管理与来宾接待；业务科研区位于背街或内庭一侧，设置独立员工主出入口与访客通道，且通过中庭/架空层与藏品流线连通但互不交叉。",
    "layout_style": "采用“大空间+独立办公室”混合：开放工位承担采编、策研、数字平台与信息管理，安静需求高的业务（撰稿、评审、档案）置于靠近静区的小隔间；会议室与小型讨论区沿走廊灵活布置；开放区与背街货梯/楼梯紧密联系，减少穿馆内公共区的时间与可视暴露。"
  },
  "circulation_strategy": "构建“藏品流线、员工流线、观众流线”三套完全分离的交通系统：藏品从外侧卸载区→库前区→内部库房，呈封闭、不可逆环路，专用货运电梯与内部通道；员工从背街员工门→内部连廊→各业务区，避开展览动线与观众中庭；观众经主入口→公共中庭→展区，仅可到达前场与对外服务点。采用“前后场”模式：藏品与员工流线完全后置，前后场之间设受控接口（刷卡、陪同、登记）；对公众可开放的服务配套（如对外小展厅、教育课堂）与对外咖啡/餐饮置入公共侧，不与库前区与科研区相互干扰。必要时设置单向流线与门禁分级，确保任何时段的可溯源与最小交叉。"
}
